update public.learning_paths
set
  title = 'Shakespeare',
  goal = 'Shakespeare',
  summary = 'Students place Shakespeare within Renaissance humanism, Reformation culture, London theater, print, patronage, and the social life of performance, and build skill with vocabulary, syntax, rhetoric, blank verse, prose, and dramatic speech. They read plays as scripts for embodied performance and study comedy, tragedy, history, romance, and lyric through form, sources, gender, race, religion, textual transmission, and global adaptation. Critical methods lead to a capstone that joins close reading, performance insight, context, criticism, and revision.',
